package com.avizero.avidrive.api;
import com.avizero.avidrive.domain.*; import com.avizero.avidrive.repository.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/public/{token}") public class PublicLinkController {private final LinkRepository links;private final StoredFileRepository files;private final FolderRepository folders;private final UserRepository users;private final PasswordEncoder encoder;private final AccessTokenRepository accessTokens;public PublicLinkController(LinkRepository l,StoredFileRepository f,FolderRepository d,UserRepository u,PasswordEncoder e,AccessTokenRepository t){links=l;files=f;folders=d;users=u;encoder=e;accessTokens=t;}
 @GetMapping("/meta") public ResponseEntity<?> meta(@PathVariable String token){Link l=find(token);if(l==null)return error(404,"Ссылка недействительна или истекла");boolean expired=expired(l);if(expired)return error(410,"Ссылка истекла");l.viewCount++;touch(l);String name=l.fileId!=null?files.findById(l.fileId).map(x->x.name).orElse(""):folders.findById(l.folderId).map(x->x.name).orElse("");return ResponseEntity.ok(Map.of("type",l.fileId!=null?"FILE":"FOLDER","name",name,"requires_password",l.passwordHash!=null,"expired",false,"can_view",l.canView,"can_download",l.canDownload,"can_upload",l.canUpload,"can_delete",l.canDelete,"can_rename",l.canRename,"owner_quota_exhausted",quotaFull(l)));}
  @PostMapping("/unlock") public ResponseEntity<?> unlock(@PathVariable String token,@RequestBody Map<String,String> body){Link l=find(token);if(l==null||expired(l))return error(404,"Ссылка недействительна или истекла");if(l.passwordHash!=null&&!encoder.matches(body.getOrDefault("password",""),l.passwordHash))return error(401,"Неверный пароль");String raw=UUID.randomUUID().toString()+UUID.randomUUID();AccessToken a=new AccessToken();a.linkId=l.id;a.tokenHash=hash(raw);a.createdAt=Instant.now().toString();a.expiresAt=Instant.now().plusSeconds(900).toString();accessTokens.save(a);return ResponseEntity.ok(Map.of("access_token",raw,"expires_at",a.expiresAt));}
  @GetMapping("/files") public ResponseEntity<?> list(@PathVariable String token,@RequestHeader(value="X-Public-Access-Token",required=false)String access,@RequestParam(required=false)Long folder_id){Link l=find(token);if(l==null||expired(l)||!l.canView||!authorized(l,access))return error(403,"Просмотр запрещён");Long root=l.folderId;if(root==null)return ResponseEntity.ok(List.of());Long folder=folder_id==null?root:folder_id;List<Map<String,Object>> result=new ArrayList<>();folders.findByOwnerIdAndParentId(l.ownerId,folder).forEach(x->result.add(Map.of("id",x.id,"type","FOLDER","name",x.name)));files.findByOwnerIdAndFolderId(l.ownerId,folder).forEach(x->result.add(Map.of("id",x.id,"type","FILE","name",x.name,"size_bytes",x.sizeBytes)));return ResponseEntity.ok(result);}
  @GetMapping("/download/{id}") public ResponseEntity<?> download(@PathVariable String token,@RequestHeader(value="X-Public-Access-Token",required=false)String access,@PathVariable Long id){Link l=find(token);if(l==null||expired(l)||!l.canDownload||!authorized(l,access))return error(403,"Скачивание запрещено");StoredFile f=files.findById(id).filter(x->x.ownerId.equals(l.ownerId)).orElse(null);if(f==null)return error(404,"Файл не найден");PathHolder p=new PathHolder(f.storagePath);if(!p.file())return error(404,"Файл не найден");l.downloadCount++;touch(l);return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+f.name.replace("\"","_")+"\"").body(p.resource());}
  private Link find(String t){return links.findByToken(t).orElse(null);}private boolean expired(Link l){return l.expiresAt!=null&&Instant.parse(l.expiresAt).isBefore(Instant.now());}private boolean authorized(Link l,String raw){if(l.passwordHash==null)return true;if(raw==null)return false;return accessTokens.findByTokenHash(hash(raw)).filter(x->x.linkId.equals(l.id)).map(x->Instant.parse(x.expiresAt).isAfter(Instant.now())).orElse(false);}private String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}private void touch(Link l){l.lastAccessedAt=Instant.now().toString();links.save(l);}private boolean quotaFull(Link l){return users.findById(l.ownerId).map(u->u.quotaMb!=null&&u.quotaMb>0&&u.usedBytes>=u.quotaMb*1024*1024).orElse(true);}private ResponseEntity<Map<String,String>> error(int s,String m){return ResponseEntity.status(s).body(Map.of("message",m));}private record PathHolder(String value){boolean file(){return java.nio.file.Files.isRegularFile(java.nio.file.Path.of(value));}org.springframework.core.io.Resource resource(){return new org.springframework.core.io.FileSystemResource(value);}}
}
